import 'dart:io' as io;

import 'package:file/file.dart' as fs;
import 'package:file/local.dart';
import 'package:flutter_cache_manager/flutter_cache_manager.dart';
import 'cache_directory_provider.dart';

class ImageCacheFileSystem implements FileSystem {
  ImageCacheFileSystem({CacheDirectoryProvider? directories})
      : _directories = directories ?? CacheDirectoryProvider();
  final CacheDirectoryProvider _directories;

  // Startup reconciliation only removes names generated by the image cache.
  static final _managedName = RegExp(
      r'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}(\.[a-zA-Z0-9_-]+)?$');

  static bool isManagedName(String name) => _managedName.hasMatch(name);

  @override
  Future<fs.File> createFile(String name) async {
    if (name.isEmpty ||
        name == '.' ||
        name == '..' ||
        name.contains('/') ||
        name.contains('\\') ||
        name.contains(':')) {
      throw ArgumentError.value(name);
    }
    final directory = await _directories.directory('images');
    return const LocalFileSystem().file('${directory.path}/$name');
  }

  Future<List<fs.File>> managedFiles() async {
    final directory = await _directories.directory('images');
    final files = <fs.File>[];
    await for (final entity in directory.list(followLinks: false)) {
      final name = entity.uri.pathSegments.last;
      if (entity is io.File && isManagedName(name)) {
        files.add(const LocalFileSystem().file(entity.path));
      }
    }
    return files;
  }
}
